code.source:
#include <iostream>
using namespace std;

int main() {
    int fish = 3;
    int* p = nullptr;
    if (p == nullptr) {
        cout << "p points to nothing" << endl;
    }
    p = &fish;
    if (p) {
        cout << *p << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int* find_item(int a[], int n, int target) {
    for (int i = 0; i < n; i++) {
        if (a[i] == target) {
            return &a[i];
        }
    }
    return nullptr;
}

int main() {
    int a[3] = {4, 8, 15};
    int* hit = find_item(a, 3, 8);
    if (hit != nullptr) {
        cout << "Found " << *hit << endl;
    }
    if (find_item(a, 3, 99) == nullptr) {
        cout << "Not found" << endl;
    }
    return 0;
}

